import numpy as np
t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
best=None
for k0 in np.linspace(0.05,1.5,30):
  for k2 in np.linspace(0.05,1.5,30):
    X=np.column_stack([np.ones_like(t), np.exp(-k0*t), t, t**2, A, A**2, A**3, A**2*t*np.exp(-k2*t)])
